	"package.json":
		'{\n\t"name": "com.thinkrail.bridge",\n\t"version": "0.4.0",\n\t"displayName": "UnityRail Unity Bridge",\n\t"description": "Gives the UnityRail AI IDE eyes and hands inside the Unity Editor: compile diagnostics, Console, Play Mode, Game/Scene screenshots, tests, hierarchy, inspection and asset search — and hands that edit the scene, build, manage packages/settings, profile, synthesize input and quit the Editor.",\n\t"unity": "2022.3",\n\t"documentationUrl": "https://github.com/thinkrail/thinkrail",\n\t"licensesUrl": "https://github.com/thinkrail/thinkrail/blob/main/LICENSE",\n\t"keywords": [\n\t\t"thinkrail",\n\t\t"ai",\n\t\t"agent",\n\t\t"editor",\n\t\t"automation"\n\t],\n\t"author": {\n\t\t"name": "UnityRail",\n\t\t"url": "https://github.com/thinkrail"\n\t},\n\t"dependencies": {\n\t\t"com.unity.nuget.newtonsoft-json": "3.2.1",\n\t\t"com.unity.test-framework": "1.1.33"\n\t}\n}\n',
